def is_managed_runtime_start_gate(label: str) -> bool:
    return "managed runtime start executed once" in " ".join(label.lower().split())


def is_managed_runtime_health_gate(label: str) -> bool:
    return "current managed runtime health" in " ".join(label.lower().split())


def loopback_address(value: str) -> bool:
    try:
        if value.startswith("["):
            host, separator, port = value[1:].partition("]:")
        else:
            host, separator, port = value.rpartition(":")
        return bool(separator) and ipaddress.ip_address(host).is_loopback and 1 <= int(port) <= 65535
    except ValueError:
        return False


def runtime_process_command(command: list[str], operation: str, project: Path) -> dict[str, str] | None:
    cli_name = "domainry-cli.exe" if os.name == "nt" else "domainry-cli"
    expected_cli = Path(__file__).resolve().parent / cli_name
    try:
        command_cli = Path(command[0]).expanduser().resolve(strict=True) if command else None
    except OSError:
        command_cli = None
    if (
        len(command) < 4
        or command_cli != expected_cli
        or command_cli.is_symlink()
        or not command_cli.is_file()
        or command[1:3] != ["runtime-process", operation]
    ):
        return None
    allowed = {"--project"} if operation == "status" else {"--project", "--bundle", "--address"}
    values: dict[str, str] = {}
    index = 3
    while index < len(command):
        token = command[index]
        if "=" in token:
            option, value = token.split("=", 1)
            index += 1
        else:
            option = token
            if index + 1 >= len(command):
                return None
            value = command[index + 1]
            index += 2
        if option not in allowed or option in values or not value or value.startswith("--"):
            return None
        values[option] = value
    if set(values) != allowed:
        return None
    try:
        if Path(values["--project"]).expanduser().resolve() != project:
            return None
    except OSError:
        return None
    if operation == "start":
        bundle = values["--bundle"]
        bundle_path = Path(bundle)
        if bundle_path.is_absolute() or ".." in bundle_path.parts or "\\" in bundle:
            return None
        if not loopback_address(values["--address"]):
            return None
        try:
            package = json.loads((project / PACKAGE_RECEIPT).read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            return None
        if not isinstance(package, dict) or package.get("bundle_path") != bundle:
            return None
    return values


