def runtime_string(document: dict, key: str, maximum: int = 4096, *, required: bool = True) -> str:
    value = document.get(key)
    if not isinstance(value, str) or (required and not value) or len(value) > maximum:
        raise GateError(f"managed Runtime JSON {key} is invalid or exceeds its bound")
    if any(ord(character) < 32 for character in value):
        raise GateError(f"managed Runtime JSON {key} contains control characters")
    return value


def validate_managed_runtime_state(document: dict, project: Path, expected_address: str) -> None:
    if set(document) - MANAGED_RUNTIME_FIELDS or not MANAGED_RUNTIME_REQUIRED_FIELDS <= set(document):
        raise GateError("managed Runtime JSON does not match the supported v3 schema")
    if document.get("contract_version") != MANAGED_RUNTIME_CONTRACT:
        raise GateError("managed Runtime JSON contract is not the supported v3 response contract")
    if document.get("state") != "running" or document.get("cohort_state") != "current":
        raise GateError("managed Runtime is not running in the current cohort")
    if document.get("healthy") is not True or document.get("health_status") != 200:
        raise GateError("managed Runtime is not healthy with HTTP status 200")
    if document.get("database_cohort_state") != "current":
        raise GateError("managed Runtime database cohort is not current")
    if runtime_string(document, "project_root") != str(project):
        raise GateError("managed Runtime project root differs from the Gate project")
    address = runtime_string(document, "address", 128)
    if address != expected_address or not loopback_address(address):
        raise GateError("managed Runtime address differs from the explicit loopback command address")
    if runtime_string(document, "origin", 256) != "http://" + address or runtime_string(document, "api_base_url", 256) != "http://" + address:
        raise GateError("managed Runtime URL identity differs from its loopback address")
    for key in ("pid", "process_group_id"):
        value = document.get(key)
        if isinstance(value, bool) or not isinstance(value, int) or value <= 0:
            raise GateError(f"managed Runtime JSON {key} is invalid")
    for key in (
        "bundle_manifest_sha256", "package_receipt_sha256", "verification_receipt_sha256",
        "finalization_receipt_sha256", "project_source_tree_sha256", "binary_sha256",
        "database_identity_sha256", "runtime_manifest_sha256",
    ):
        delivery_sha(document, key)
    driver = runtime_string(document, "database_driver", 32)
    if driver not in {"sqlite", "mysql", "postgres"}:
        raise GateError("managed Runtime database driver is unsupported")
    dsn_identity = document.get("database_dsn_identity_sha256", "")
    if driver == "sqlite":
        if dsn_identity or "database" not in document or document.get("database_schema"):
            raise GateError("managed Runtime SQLite binding is invalid")
    else:
        if not isinstance(dsn_identity, str) or not re.fullmatch(r"[0-9a-f]{64}", dsn_identity):
            raise GateError("managed Runtime external database DSN identity is invalid")
        if document.get("database"):
            raise GateError("managed Runtime external database response exposes an unexpected path")
    runtime_string(document, "bundle_manifest")
    runtime_string(document, "binary")
    runtime_string(document, "runtime_manifest")
    runtime_string(document, "log")
    runtime_string(document, "started_at", 128)
    if document.get("stopped_at"):
        raise GateError("running managed Runtime unexpectedly carries a stopped timestamp")


def runtime_artifact(project: Path, raw_path: str, description: str) -> tuple[Path, dict]:
    path = safe_project_file(project, raw_path)
    if path is None:
        raise GateError(f"managed Runtime {description} path is not a current project file")
    return path, evidence_item(project, str(path))


